arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s' "x-access-token" ;;
  *[Pp]assword*) printf '%s' "$GITHUB_TOKEN" ;;
  *) printf '%s' "" ;;
esac
EOF
chmod 700 /tmp/askpass.sh; ls -l /tmp/askpass.sh; test -n "$GITHUB_TOKEN" && echo "token env present" || echo "NO TOKEN"
